"use strict";

(function () {
  const SVG_NS = "http://www.w3.org/2000/svg";

  const BASE_WIDTH = 1610;
  const BASE_HEIGHT = 755;

  const DEFAULT_TITLE =
    "LÍNEA 3 / VISTA GENERAL 02";

  const DEFAULT_SUBTITLE =
    "Disposición del prensador, carro y levantador";

  const SENSOR_TAGS = [
    "-B621",
    "-B622",
    "-B623",
    "-B624",
    "-B625",
    "-B626",
    "-B627",
    "-B628",
    "-B629"
  ];

  const MOTOR_TAGS = [
    "-M422",
    "-M427",
    "-M442",
    "-M447",
    "-M462",
    "-M467",
    "-M482",
    "-M487"
  ];

  const STATION_START_X = 470;
  const STATION_STEP = 112;
  const STATION_WIDTH = 92;

  const STATION_TOP = 232;
  const STATION_HEIGHT = 104;

  const SENSOR_TOP = 142;
  const SENSOR_SIZE = 42;

  let root = null;
  let stage = null;
  let latestWidget = null;
  let resizeObserver = null;
  let initialized = false;
  let currentName = null;

  function svgElement(tag, attributes, parent, text) {
    const element = document.createElementNS(SVG_NS, tag);

    Object.keys(attributes || {}).forEach(function (key) {
      element.setAttribute(key, String(attributes[key]));
    });

    if (text !== undefined) {
      element.textContent = text;
    }

    if (parent) {
      parent.appendChild(element);
    }

    return element;
  }

  function buildStations() {
    const parent = document.getElementById("vg02-stations");
    parent.replaceChildren();

    SENSOR_TAGS.forEach(function (tag, index) {
      const x = STATION_START_X + index * STATION_STEP;
      const sensorAxisX = x + 78;
      const pointX = x + 14;
      const pointY = index === 0 ? 246 : 323;

      const group = svgElement("g", {}, parent);

      svgElement(
        "text",
        {
          class: "sensor-tag",
          x: sensorAxisX,
          y: SENSOR_TOP - 10
        },
        group,
        tag
      );

      svgElement(
        "use",
        {
          href: "#vg02-sensor",
          x: sensorAxisX - SENSOR_SIZE / 2,
          y: SENSOR_TOP,
          width: SENSOR_SIZE,
          height: SENSOR_SIZE
        },
        group
      );

      svgElement(
        "rect",
        {
          class: "station-body",
          x: x,
          y: STATION_TOP,
          width: STATION_WIDTH,
          height: STATION_HEIGHT,
          rx: 2
        },
        group
      );

      // Solo se conserva la línea vertical punteada.
      svgElement(
        "path",
        {
          class: "axis-line",
          d:
            "M" + sensorAxisX +
            " " + (SENSOR_TOP + SENSOR_SIZE + 4) +
            "V379"
        },
        group
      );

      svgElement(
        "path",
        {
          class: "mechanical-line",
          d:
            "M" + (sensorAxisX - 6) +
            " 379H" + (sensorAxisX + 6)
        },
        group
      );

      svgElement(
        "circle",
        {
          class: "station-point",
          cx: pointX,
          cy: pointY,
          r: 9
        },
        group
      );
    });
  }

  function buildMotors() {
    const parent = document.getElementById("vg02-motors");
    parent.replaceChildren();

    MOTOR_TAGS.forEach(function (tag, index) {
      const stationIndex = index + 1;
      const stationX =
        STATION_START_X + stationIndex * STATION_STEP;

      const centerX = stationX + 14;
      const group = svgElement("g", {}, parent);

      svgElement(
        "path",
        {
          class: "motor-connection",
          d:
            "M" + centerX + " 426" +
            "V" + (STATION_TOP + STATION_HEIGHT + 4)
        },
        group
      );

      svgElement(
        "text",
        {
          class: "motor-tag",
          x: centerX,
          y: 451
        },
        group,
        tag
      );

      svgElement(
        "circle",
        {
          class: "motor-circle",
          cx: centerX,
          cy: 482,
          r: 18
        },
        group
      );

      svgElement(
        "text",
        {
          class: "motor-letter",
          x: centerX,
          y: 482
        },
        group,
        "M"
      );
    });
  }

  function fitHeader() {
    if (!stage) return;

    [
      [".screen-title", 28],
      [".screen-subtitle", 14]
    ].forEach(function (entry) {
      const element = stage.querySelector(entry[0]);

      if (!element || element.hidden) return;

      element.style.fontSize = entry[1] + "px";

      if (
        element.clientWidth > 0 &&
        element.scrollWidth > element.clientWidth
      ) {
        element.style.fontSize =
          (
            entry[1] *
            element.clientWidth /
            element.scrollWidth
          ) + "px";
      }
    });
  }

  function updateHeader(widget) {
    if (!stage) return;

    const name =
      widget && typeof widget.name === "string"
        ? widget.name.trim()
        : "";

    if (name === currentName) return;
    currentName = name;

    const separator = name.indexOf("//");

    const titleText =
      separator < 0
        ? name
        : name.slice(0, separator).trim();

    const subtitleText =
      separator < 0
        ? DEFAULT_SUBTITLE
        : name.slice(separator + 2).trim();

    const title = stage.querySelector(".screen-title");
    const subtitle = stage.querySelector(".screen-subtitle");

    title.textContent = titleText || DEFAULT_TITLE;
    subtitle.textContent = subtitleText;
    subtitle.hidden = subtitleText === "";

    fitHeader();
  }

  function fitStage() {
    if (!root || !stage) return;

    const width = root.clientWidth;
    const height = root.clientHeight;

    if (width <= 0 || height <= 0) return;

    const scale = Math.min(
      width / BASE_WIDTH,
      height / BASE_HEIGHT
    );

    stage.style.left =
      ((width - BASE_WIDTH * scale) / 2) + "px";

    stage.style.top =
      ((height - BASE_HEIGHT * scale) / 2) + "px";

    stage.style.transform = "scale(" + scale + ")";
  }

  /*
   * Widget visual, sin variables del PLC.
   * NOMBRE permite cambiar el encabezado: Título//Subtítulo.
   */
  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;

    if (initialized) {
      updateHeader(widget);
    }
  };

  function initialize() {
    if (initialized) return;

    root = document.querySelector(".overview-widget");
    stage = document.querySelector(".overview-stage");

    if (!root || !stage) return;

    buildStations();
    buildMotors();

    initialized = true;

    updateHeader(latestWidget || window.WIDGET || null);
    fitStage();

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(fitStage);
      resizeObserver.observe(root);
    } else {
      window.addEventListener("resize", fitStage);
    }

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(function () {
        fitHeader();
        fitStage();
      });
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
